<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import type {AttendanceDetail,Correction} from '../types'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),id=String(route.params.id),scheduleId=String(route.query.schedule||''),{api,home,t,p,base,loading,busy,failure,notice,load,write,format}=usePhasePage(),data=ref<AttendanceDetail|null>(null),item=ref<Correction|null>(null),note=ref('')
const mine=computed(()=>!!item.value&&item.value.applicantId===home.value?.myself?.accountId),selfEmployee=computed(()=>item.value?.employeeId===home.value?.myself?.id)
function refresh(){if(!scheduleId){failure.value=p('invalid');return}void load(()=>api().get<AttendanceDetail>('/attendance/'+scheduleId),v=>{data.value=v;item.value=v.corrections.find(c=>c.id===id)||null;if(!item.value)failure.value=t('notFound')})}
function decide(status:'approved'|'rejected'|'withdrawn'){if(!item.value||busy.value)return;if(status!=='withdrawn'&&!note.value.trim()){failure.value=p('invalid');return}void write(()=>api().put('/corrections/'+id+'/decision',{expectedVersion:item.value!.version,status,note:note.value.trim()}),refresh)}
onMounted(refresh)
</script>
<template><section class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{p('correction')}}</h2><button :disabled="loading||busy" @click="refresh">{{t('refresh')}}</button></header><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="item&&data&&!loading"><dl class="wf-details"><dt>{{p('employee')}}</dt><dd>{{item.employeeName}}</dd><dt>{{p('status')}}</dt><dd><span class="wf-badge">{{p(item.status)}}</span></dd><dt>{{p('workDate')}}</dt><dd><RouterLink :to="base+'/attendance/'+item.scheduleId">{{data.attendance.schedule.workDate}} · {{data.attendance.schedule.shift.name}}</RouterLink></dd><dt>{{p('timezone')}}</dt><dd>{{data.attendance.schedule.timezone}}</dd><dt>{{p('inAt')}}</dt><dd>{{format(item.inAt,data.attendance.schedule.timezone)}}</dd><dt>{{p('outAt')}}</dt><dd>{{format(item.outAt,data.attendance.schedule.timezone)}}</dd><dt>{{p('breaks')}}</dt><dd><div v-for="(b,i) in item.breaks" :key="i">{{format(b.start,data.attendance.schedule.timezone)}} – {{format(b.end,data.attendance.schedule.timezone)}}</div><span v-if="!item.breaks.length">—</span><p v-if="item.overrideBreak">{{p('overrideBreak')}}</p></dd><dt>{{p('reason')}}</dt><dd class="wf-preserve">{{item.reason}}</dd><dt>{{p('created')}}</dt><dd>{{format(item.createdAt,data.attendance.schedule.timezone)}}</dd><dt v-if="item.reviewNote">{{p('note')}}</dt><dd v-if="item.reviewNote" class="wf-preserve">{{item.reviewNote}}</dd><dt v-if="item.reviewerId">{{p('reviewer')}}</dt><dd v-if="item.reviewerId">{{item.reviewerId}}</dd></dl><template v-if="item.status==='pending'"><p v-if="selfEmployee&&home?.employeeManage" class="wf-hint">{{p('selfReview')}}</p><form v-if="home?.employeeManage&&!selfEmployee&&!mine" class="wf-section" @submit.prevent="decide('approved')"><label>{{p('note')}}<textarea v-model="note" required maxlength="500" rows="3" :disabled="busy"></textarea></label><footer class="wf-form-actions"><button type="button" :disabled="busy||!note.trim()" @click="decide('rejected')">{{p('reject')}}</button><button class="primary" :disabled="busy||!note.trim()">{{busy?t('saving'):p('approve')}}</button></footer></form><button v-if="mine" class="wf-section" :disabled="busy" @click="decide('withdrawn')">{{p('withdraw')}}</button></template></template></section></template>
